 cancelFocus(){cancelAnimationFrame(this.raf);this.raf=0;}
 focus(coords){this.cancelFocus();const target=[-coords[0],-coords[1],0];let delta=((target[0]-this.rotation[0]+540)%360)-180;const start=[...this.rotation],t0=performance.now(),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?0:520;const step=t=>{const f=duration?Math.min(1,(t-t0)/duration):1,k=1-(1-f)**3;this.rotation=[start[0]+delta*k,start[1]+(target[1]-start[1])*k,0];this.draw();if(f<1)this.raf=requestAnimationFrame(step);};this.raf=requestAnimationFrame(step);}
